-  for (const AddressedLoad &addressed : candidate.loads) {
-    triton::LoadOp load = addressed.load;
-    DenseMap<Value, int64_t> tileVisited;
-    if (!tileReachesOnlyGuardedStores(load.getResult(), addressed.dim,
