-  // self block_id
-  auto selfBlockId = CVPipeline::getOpBlockId(ifOp);
-  cand.selfBlockId = selfBlockId.value_or(-1);
-
-  // Group then region
-  cand.thenGroups = groupOpsInBlock(*ifOp.thenBlock());
-
-  // Group else region
-  Block *elseBlk = ifOp.elseBlock();
-  if (elseBlk) {
-    cand.elseGroups = groupOpsInBlock(*elseBlk);
-  }
